PRAGMA foreign_keys=ON;
CREATE TABLE sources(source_id INTEGER PRIMARY KEY,path TEXT NOT NULL UNIQUE,sha256 TEXT NOT NULL,format TEXT NOT NULL,input_rows INTEGER NOT NULL);
CREATE TABLE genes(gene_id TEXT PRIMARY KEY,chromosome TEXT,start_position INTEGER,end_position INTEGER,strand TEXT,annotation_source INTEGER REFERENCES sources(source_id), CHECK(start_position IS NULL OR (start_position>0 AND end_position>=start_position)), CHECK(strand IS NULL OR strand IN ('+','-','.','?')));
CREATE TABLE gene_aliases(original_id TEXT NOT NULL,gene_id TEXT NOT NULL REFERENCES genes(gene_id),source_id INTEGER NOT NULL REFERENCES sources(source_id),PRIMARY KEY(original_id,source_id));
CREATE TABLE traits(trait_id INTEGER PRIMARY KEY,trait_name TEXT NOT NULL UNIQUE,metabolite_class TEXT);
CREATE TABLE trait_genes(trait_id INTEGER NOT NULL REFERENCES traits(trait_id),gene_id TEXT NOT NULL REFERENCES genes(gene_id),PRIMARY KEY(trait_id,gene_id));
CREATE TABLE candidate_records(source_id INTEGER NOT NULL REFERENCES sources(source_id),row_number INTEGER NOT NULL,trait_id INTEGER NOT NULL,gene_id TEXT NOT NULL,original_id TEXT NOT NULL,PRIMARY KEY(source_id,row_number),FOREIGN KEY(trait_id,gene_id) REFERENCES trait_genes(trait_id,gene_id));
CREATE TABLE go_terms(go_id TEXT PRIMARY KEY,go_name TEXT,ontology TEXT,current_go_id TEXT,annotation_provider TEXT,source_id INTEGER REFERENCES sources(source_id));
CREATE TABLE gene_go(gene_id TEXT NOT NULL REFERENCES genes(gene_id),go_id TEXT NOT NULL REFERENCES go_terms(go_id),source_id INTEGER NOT NULL REFERENCES sources(source_id),PRIMARY KEY(gene_id,go_id));
CREATE TABLE annotation_records(source_id INTEGER NOT NULL REFERENCES sources(source_id),row_number INTEGER NOT NULL,gene_id TEXT NOT NULL REFERENCES genes(gene_id),raw_go TEXT,status TEXT NOT NULL,PRIMARY KEY(source_id,row_number));
CREATE TABLE associations(association_id INTEGER PRIMARY KEY,trait_id INTEGER NOT NULL REFERENCES traits(trait_id),snp_id TEXT NOT NULL,chromosome_original TEXT,chromosome_forced TEXT,position INTEGER CHECK(position>0),p_value REAL CHECK(p_value>=0 AND p_value<=1),minus_log10_p REAL,source_id INTEGER NOT NULL REFERENCES sources(source_id),UNIQUE(trait_id,snp_id,source_id));
CREATE TABLE association_genes(association_id INTEGER NOT NULL REFERENCES associations(association_id),gene_id TEXT NOT NULL REFERENCES genes(gene_id),distance_to_gene INTEGER,annotation TEXT,gene_name TEXT,reported_chromosome TEXT,reported_start INTEGER,reported_end INTEGER,original_gene_id TEXT,PRIMARY KEY(association_id,gene_id));
CREATE TABLE association_records(source_id INTEGER NOT NULL REFERENCES sources(source_id),row_number INTEGER NOT NULL,association_id INTEGER NOT NULL REFERENCES associations(association_id),gene_id TEXT NOT NULL REFERENCES genes(gene_id),raw_json TEXT NOT NULL,PRIMARY KEY(source_id,row_number));
CREATE TABLE analysis_runs(run_id TEXT PRIMARY KEY,parameters_json TEXT NOT NULL,session_info TEXT NOT NULL,input_manifest_sha256 TEXT NOT NULL);
CREATE TABLE enrichment_results(run_id TEXT NOT NULL REFERENCES analysis_runs(run_id),trait_id INTEGER NOT NULL REFERENCES traits(trait_id),go_id TEXT NOT NULL REFERENCES go_terms(go_id),p_value REAL NOT NULL,adjusted_p_value REAL NOT NULL,q_value REAL,gene_count INTEGER NOT NULL,background_count INTEGER NOT NULL,gene_ratio TEXT NOT NULL,background_ratio TEXT NOT NULL,significant INTEGER NOT NULL CHECK(significant IN(0,1)),PRIMARY KEY(run_id,trait_id,go_id));
CREATE TABLE enrichment_genes(run_id TEXT NOT NULL,trait_id INTEGER NOT NULL,go_id TEXT NOT NULL,gene_id TEXT NOT NULL REFERENCES genes(gene_id),PRIMARY KEY(run_id,trait_id,go_id,gene_id),FOREIGN KEY(run_id,trait_id,go_id) REFERENCES enrichment_results(run_id,trait_id,go_id));
CREATE VIEW background_genes AS SELECT DISTINCT gene_id FROM gene_go;
